class Solution {
    int answer = 0;
    long long dfs(TreeNode* node) {
        if (!node) return 0;
        long long descendants = dfs(node->left) + dfs(node->right);
        if (descendants == node->val) ++answer;
        return descendants + node->val;
    }
public:
    int equalToDescendants(TreeNode* root) {
        answer = 0;
        dfs(root);
        return answer;
    }
};
